import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`review-response`,heroTitle:`Handle every review in minutes`,heroSubtitle:`Perplexity Computer pulls your negative reviews, drafts professional responses, and builds a product improvement report — automatically.`,inputUrlCta:`Analyze my reviews`,inputUrlPlaceholder:`yourstore.com`,inputUrlPrefill:`Go to {url} and perform a complete review response and analysis workflow. 1) Pull all negative reviews (1-3 stars) from the store, capturing the reviewer name, star rating, date, and full review text. 2) Categorize each review by complaint theme — shipping, product quality, sizing/fit, packaging, customer service, missing items, and any other recurring themes. 3) Draft a professional, empathetic response for each negative review that acknowledges the issue, offers a resolution path, and reinforces the brand's commitment to quality. Match the tone to the brand voice on the store page. 4) Identify the top recurring complaint themes and rank them by frequency and severity. 5) Deliver a product improvement report with specific, actionable recommendations for each theme — including which SKUs are most affected. 6) Output everything in a spreadsheet with columns: review text, star rating, date, complaint theme, drafted response, and improvement recommendation.`,heroOverlaySteps:[`Pulling negative and 3-star reviews from your store`,`Categorizing complaints by theme — shipping, quality, sizing, and more`,`Drafting professional responses for each review`,`Responses drafted, improvement report compiled — ready to publish`],generatingSteps:[`Visiting {url} to extract reviews, ratings, and product details`,`Designing an agent to categorize complaints by theme and severity`,`Configuring response drafting with brand-matched tone for each review`,`Setting up product improvement report with recurring issue analysis`],featureSectionTitle:`From reviews to responses and insights`,featureCardTitles:[`Connects to your ecommerce stack`,`Outputs you can publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Shopify, Google Sheets, Zendesk, Slack, Notion — Computer plugs into your tools so review responses flow from analysis to your support workflow.`,`Drafted responses for every negative review. Complaint theme breakdowns by SKU. A prioritized product improvement report with actionable fixes.`],capabilitySectionTitle:`Your review team, on autopilot`,capabilitySectionSubtitle:`Paste your store URL, step away, come back to drafted responses and a product improvement plan.`,capabilityCards:[{title:`Review Extraction`,description:`Computer can pull every negative and 3-star review from your Amazon or Shopify store — capturing ratings, dates, and full review text.`},{title:`Complaint Categorization`,description:`Computer can sort every complaint by theme — shipping, quality, sizing, packaging, customer service — and rank themes by frequency and severity.`},{title:`Response Drafting`,description:`Computer can write professional, empathetic responses for each review — acknowledging the issue, offering resolution, and matching your brand voice.`},{title:`Connect Your Tools`,description:`Computer can push responses to Zendesk, log insights in Google Sheets, notify your team in Slack, and update docs in Notion — all in one workflow.`},{title:`Learns Your Brand`,description:`Computer can remember your brand voice, past responses, and recurring issues across sessions — so every batch of responses stays consistent and improves over time.`},{title:`Monitor & Alert`,description:`Computer can check for new negative reviews daily and alert you when a new complaint theme emerges or a product's rating starts dropping.`}]});export{t as default};
